{"output": "from collections import Counter, defaultdict


def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    out = [row[:] for row in grid]

    # Collinear same-color diagonal segments indicate lines to continue.
    for color in set(v for row in grid for v in row if v != background):
        for dr, dc, keyfn in ((1, 1, lambda r, c: r - c),
                              (1, -1, lambda r, c: r + c)):
            groups = defaultdict(list)
            for r in range(h):
                for c in range(w):
                    if grid[r][c] == color:
                        groups[keyfn(r, c)].append((r, c))
            for pts in groups.values():
                if len(pts) < 2:
                    continue
                # Along either diagonal orientation, walk outward from both
                # ends; stop when reaching a different object/color.
                pts.sort(key=lambda p: p[0])
                for r0, c0 in (pts[0], pts[-1]):
                    for sign in (-1, 1):
                        r, c = r0 - sign * dr, c0 - sign * dc
                        while 0 <= r < h and 0 <= c < w:
                            if grid[r][c] not in (background, color):
                                break
                            if out[r][c] == background:
                                out[r][c] = color
                            r += sign * dr
                            c += sign * dc
    return out


def _demo_check():
    a = [[6] * 14 for _ in range(27)]
    a[0][0], a[0][3] = 0, 1
    a[1][1], a[1][2] = 0, 1
    a[2][1], a[2][2] = 2, 9
    assert transform(a) == a

    b = [[2] * 26 for _ in range(7)]
    b[4][16], b[4][19] = 5, 9
    b[5][17], b[5][18] = 5, 9
    b[6][17], b[6][18] = 8, 5
    expected = [row[:] for row in b]
    for r in range(5):
        expected[r][12 + r] = 5
        expected[r][23 - r] = 9
    assert transform(b) == expected

if __name__ == '__main__':
    _demo_check()
    print('demonstrations verified')
